package com.brightloop.invoice;
import java.math.BigDecimal;import java.time.LocalDate;import java.time.Instant;import java.util.List;
public final class InvoiceDtos {private InvoiceDtos(){}public record Line(Long id,Long productId,String productName,String description,int quantity,BigDecimal unitPrice,BigDecimal taxRate,BigDecimal taxAmount,BigDecimal lineTotal){static Line of(InvoiceLine l){return new Line(l.getId(),l.getProduct().getId(),l.getProduct().getName(),l.getDescription(),l.getQuantity(),l.getUnitPrice(),l.getTaxRate(),l.getTaxAmount(),l.getLineTotal());}}public record Response(Long id,String invoiceNumber,Long customerId,String customerName,String customerEmail,Long subscriptionId,String billingPeriodStart,String billingPeriodEnd,LocalDate issueDate,LocalDate dueDate,String status,BigDecimal subtotal,BigDecimal taxAmount,BigDecimal discountAmount,BigDecimal total,BigDecimal amountPaid,BigDecimal outstanding,List<Line> lines){public static Response of(Invoice i){return new Response(i.getId(),i.getInvoiceNumber(),i.getCustomer().getId(),i.getCustomer().getFullName(),i.getCustomer().getEmail(),i.getSubscription()==null?null:i.getSubscription().getId(),i.getBillingPeriodStart()==null?null:i.getBillingPeriodStart().toString(),i.getBillingPeriodEnd()==null?null:i.getBillingPeriodEnd().toString(),i.getIssueDate(),i.getDueDate(),i.getStatus(),i.getSubtotal(),i.getTaxAmount(),i.getDiscountAmount(),i.getTotal(),i.getAmountPaid(),i.getOutstanding(),i.getLines().stream().map(Line::of).toList());}}}
